    # guide. Seeds project perpendicular to the nearest guide.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != seed:
                continue
            out[r][c] = 4
            guides = []
            for rr in range(h):
                for cc in range(w):
                    if grid[rr][cc] != bg and grid[rr][cc] != seed:
                        if rr in (0, h-1):
                            guides.append((abs(rr-r), 0 if rr < r else 1, rr))
                        if cc in (0, w-1):
                            guides.append((abs(cc-c), 2 if cc < c else 3, cc))
            if not guides:
                continue
            _, direction, _ = min(guides)
            if direction < 2:
                step = -1 if direction == 0 else 1
                rr = r + step
                while 0 <= rr < h and grid[rr][c] == bg:
                    out[rr][c] = seed
                    rr += step
            else:
                step = -1 if direction == 2 else 1
                cc = c + step
                while 0 <= cc < w and grid[r][cc] == bg:
                    out[r][cc] = seed
                    cc += step
